// saas/app/api/cos-primary/route.ts
// Live COS-first entrypoint. Provenance fields are assembled from execution state, never generated by a model.
import { NextRequest,NextResponse } from 'next/server'
import { POST as legacyConciergePost } from '@/app/api/concierge/route'
import { tryCOSFirstAnswer } from '@/lib/ai/cos/cosFirstAnswer'
import { tryDeterministicUtility } from '@/lib/ai/cos/deterministicUtilities'
import { resolveCosReasoner } from '@/lib/ai/cos/cosReasoner'
import { buildCosLiveTelemetry,emitCosLiveTelemetry,type CosLiveResponseSource } from '@/lib/ai/cos/cosLiveTelemetry'
import { cosConversationKey,formatCosExecutionProvenance,previousCosExecution,rememberCosExecution } from '@/lib/ai/cos/cosExecutionProvenance'
import { checkLocalInferenceHealth,localInferenceConfigFromEnv } from '@/lib/ai/local-inference'
import { getAccess } from '@/lib/auth/access'
export const runtime='nodejs';export const dynamic='force-dynamic';export const maxDuration=300
function latestUserText(body:any):string{const messages=Array.isArray(body?.messages)?body.messages:[];for(let i=messages.length-1;i>=0;i--){if(messages[i]?.role!=='user')continue;const c=messages[i]?.content;if(typeof c==='string')return c;if(Array.isArray(c))return c.map((b:any)=>String(b?.text||'')).join('\n').trim()}return''}
function languageFrom(body:any):string{const v=String(body?.context?.language||'en').toLowerCase();return['en','es','pt','pl','ru'].includes(v)?v:'en'}
function confidenceThreshold():number{const v=Number(process.env.COS_LOCAL_CONFIDENCE_THRESHOLD||'0.72');return Number.isFinite(v)?Math.max(.5,Math.min(.98,v)):.72}
function externalFallbackEnabled():boolean{return process.env.COS_EXTERNAL_AI_FALLBACK_ENABLED!=='false'}
function isProvenanceIntrospection(input:string):boolean{const p=/\b(provenance|introspection|execution provenance|execution telemetry|audit trail|model contribution|model contributions|which model|what model|primary model|reasoner|semantic cache|enterprise memory|knowledge graph|learned corpus|learning corpus|autonomous research|external ai|external provider|internal systems?)\b/i,r=/\b(previous|preceding|prior|last|just|that|this|answer|response|request|execution|used|invoked|contributed|generated|reasoning)\b/i;return p.test(input)&&r.test(input)}
function requestsExternalAction(input:string):boolean{if(isProvenanceIntrospection(input))return false;return/\b(run|execute|perform|investigate|check|fetch|pull|read|scan|audit|search|look up|research|deploy|commit|merge|create|update|delete|send|publish|queue|launch|start|fix|repair|change|modify|call the tool|use (?:the )?tools?)\b/i.test(input)&&/\b(repo|repository|github|vercel|supabase|logs?|metrics?|status page|production|database|table|file|route|api|web|internet|youtube|publication|magazine|journal|provider|campaign|prospect)\b/i.test(input)}
function providerFromPayload(payload:any){for(const item of[payload?.execution,payload?.metadata,payload?.provenance,payload]){if(!item||typeof item!=='object')continue;const provider=typeof item.provider==='string'?item.provider:typeof item.ai_provider==='string'?item.ai_provider:null,model=typeof item.model==='string'?item.model:typeof item.ai_model==='string'?item.ai_model:null;if(provider||model)return{provider,model}}return{provider:null,model:null}}
function authoritativeProvenance(cos:any,external:{invoked:boolean;provider?:string|null;model?:string|null}){const p=cos?.provenance??null,cache=p?.responseSource==='semantic_cache'||p?.responseSource==='semantic_similarity';return{schema_version:1,authority:'server_execution_telemetry',model_generated:false,semantic_cache:{used:cache,evidence_count:cache?1:0},enterprise_memory:{used:(p?.knowledgeFactsUsed??0)>0,evidence_count:p?.knowledgeFactsUsed??0},knowledge_graph:{used:(p?.knowledgeFactsUsed??0)>0,evidence_count:p?.knowledgeFactsUsed??0},learned_corpus:{used:(p?.learnedItemsUsed??0)>0,evidence_count:p?.learnedItemsUsed??0},user_memory:{used:(p?.userMemoriesUsed??0)>0,evidence_count:p?.userMemoriesUsed??0},autonomous_research:{used:p?.autonomousResearchAttempted??false,documents_acquired:p?.researchDocumentsAcquired??0,new_knowledge_retained:p?.knowledgeNewlyRetained??0},local_reasoning:{invoked:p?.localModelInvoked??false,model:p?.reasonerLabel??null,confidence:cos?.confidence??null,threshold:confidenceThreshold()},external_ai:{invoked:external.invoked,provider:external.provider??null,model:external.model??null}}}
function escalationReason(cos:any,error:string|null,action:boolean){if(error)return{code:'local_reasoner_exception',detail:error};if(action)return{code:'explicit_external_action',detail:'Delegated requested external action to governed executor.'};if(cos&&!cos.handled){const d=String(cos.reason||'COS declined the request without a reason.');if(/not configured/i.test(d))return{code:'local_reasoner_not_configured',detail:d};if(/below escalation threshold/i.test(d))return{code:'confidence_below_threshold',detail:d};if(/did not return an answer/i.test(d))return{code:'local_reasoner_no_answer',detail:d};if(/unparseable/i.test(d))return{code:'local_reasoner_unparseable',detail:d};return{code:'cos_first_declined',detail:d}}return{code:'cos_first_unavailable',detail:'COS-first attempt unavailable.'}}
function logEscalation(e:Record<string,unknown>){console.warn('[cos-escalation-audit]',JSON.stringify({at:new Date().toISOString(),...e}))}
function legacyContinuityFailure(p:any){const t=JSON.stringify(p??{}).toLowerCase();return t.includes('both reasoning providers are temporarily unavailable')||t.includes('continuity protection detected a primary failure')}
async function independentReasonerHealth(){const r=resolveCosReasoner();if('reason'in r)return{configured:false,healthy:false,model:null,error:r.reason};try{const h=await checkLocalInferenceHealth(localInferenceConfigFromEnv());return{configured:true,healthy:h.ok,model:h.model,error:h.error??null}}catch(e){return{configured:true,healthy:false,model:process.env.LOCAL_AI_MODEL?.trim()||null,error:e instanceof Error?e.message:String(e)}}}
function emitRequestTelemetry(a:{startedAt:number;input:string;reply?:string|null;source:CosLiveResponseSource;confidence?:number|null;provenance?:any;externalAiInvoked:boolean}){const p=a.provenance??null,o=buildCosLiveTelemetry({responseSource:a.source,latencyMs:Math.max(0,Date.now()-a.startedAt),confidence:a.confidence??null,reasonerLabel:p?.reasonerLabel??null,localModelInvoked:p?.localModelInvoked??false,externalAiInvoked:a.externalAiInvoked,knowledgeFactsUsed:p?.knowledgeFactsUsed??0,learnedItemsUsed:p?.learnedItemsUsed??0,userMemoriesUsed:p?.userMemoriesUsed??0,similarityScore:p?.similarityScore,promptChars:a.input.length,replyChars:String(a.reply??'').length});emitCosLiveTelemetry(o);return o}
function save(sessionId:string|null,userId:string|null,prompt:string,reply:string|null,source:string,executionProvenance:any,liveTelemetry:any){rememberCosExecution({sessionId,userId,snapshot:{at:new Date().toISOString(),prompt,reply,source,executionProvenance,liveTelemetry}})}
export async function POST(req:NextRequest){const startedAt=Date.now(),body=await req.clone().json().catch(()=>({})),input=latestUserText(body),language=languageFrom(body);if(!input)return legacyConciergePost(new NextRequest(req.clone()));const access=await getAccess().catch(()=>null),sessionId=cosConversationKey(body,req),userId=access?.userId||null
  if(isProvenanceIntrospection(input)){const prior=previousCosExecution({sessionId,userId});if(prior){const reply=formatCosExecutionProvenance(prior);return NextResponse.json({reply,source:'cos-authoritative-prior-provenance',external_ai_invoked:false,external_fallback_invoked:false,local_model_invoked:false,execution_provenance:prior.executionProvenance,prior_execution_at:prior.at,prior_response_source:prior.source,execution_allowed:false,external_action_taken:false})}}
  const deterministic=tryDeterministicUtility({prompt:input,timezone:body?.context?.timezone||body?.context?.timeZone,locale:language==='pt'?'pt-BR':language==='es'?'es':language==='pl'?'pl':language==='ru'?'ru':'en-US',confidenceThreshold:confidenceThreshold()});if(deterministic){const live=emitRequestTelemetry({startedAt,input,reply:deterministic.reply,source:'deterministic',confidence:deterministic.confidence,externalAiInvoked:false}),ep=deterministic.executionProvenance;save(sessionId,userId,input,deterministic.reply,deterministic.source,ep,live);return NextResponse.json({reply:deterministic.reply,source:deterministic.source,confidence_score:deterministic.confidence,confidence_threshold:confidenceThreshold(),external_ai_invoked:false,external_fallback_invoked:false,local_model_invoked:false,execution_provenance:ep,live_telemetry:live,execution_allowed:false,external_action_taken:false})}
  let cos:Awaited<ReturnType<typeof tryCOSFirstAnswer>>|null=null,localError:string|null=null;try{cos=await tryCOSFirstAnswer({prompt:input,userId,language,privileged:Boolean(access?.isOwner||access?.isAdmin)})}catch(e){localError=e instanceof Error?e.message:String(e);console.error('[cos-local-reasoner-error]',localError)}const action=requestsExternalAction(input)
  if(cos?.handled&&!action){const ep=authoritativeProvenance(cos,{invoked:false}),source:CosLiveResponseSource=cos.provenance.responseSource,live=emitRequestTelemetry({startedAt,input,reply:cos.reply,source,confidence:cos.confidence,provenance:cos.provenance,externalAiInvoked:false});save(sessionId,userId,input,cos.reply,source,ep,live);return NextResponse.json({reply:cos.reply,source:source==='semantic_cache'||source==='semantic_similarity'?'cos-semantic-cache':'cos-local-primary',confidence_score:cos.confidence,confidence_threshold:confidenceThreshold(),external_ai_invoked:false,external_fallback_invoked:false,local_model_invoked:cos.provenance.localModelInvoked,execution_provenance:ep,provenance:cos.provenance,live_telemetry:live,execution_allowed:false,external_action_taken:false})}
  const reason=escalationReason(cos,localError,action);logEscalation({event:'external_escalation_decision',reason_code:reason.code,reason:reason.detail,confidence:cos?.confidence??null,threshold:confidenceThreshold(),local_model_invoked:cos?.provenance?.localModelInvoked??false,local_model:cos?.provenance?.reasonerLabel??null,external_action_requested:action,fallback_enabled:externalFallbackEnabled()})
  if(!externalFallbackEnabled()){const ep=authoritativeProvenance(cos,{invoked:false}),live=emitRequestTelemetry({startedAt,input,source:'failed_closed',confidence:cos?.confidence??0,provenance:cos?.provenance,externalAiInvoked:false});save(sessionId,userId,input,null,'failed_closed',ep,live);return NextResponse.json({ok:false,error:'COS could not complete this request independently and external AI fallback is disabled.',cos_first_attempted:Boolean(cos)||Boolean(localError),cos_first_handled:false,cos_first_confidence:cos?.confidence??0,confidence_threshold:confidenceThreshold(),cos_first_reason:reason.detail,escalation_reason_code:reason.code,independent_reasoner:await independentReasonerHealth(),external_ai_invoked:false,external_fallback_invoked:false,isolation_mode:true,execution_provenance:ep,live_telemetry:live},{status:503})}
  const response=await legacyConciergePost(new NextRequest(req.clone()));try{const payload=await response.clone().json(),external=providerFromPayload(payload),failed=legacyContinuityFailure(payload),health=failed?await independentReasonerHealth():null,ep=authoritativeProvenance(cos,{invoked:!failed,...external}),reply=failed?`COS independent reasoning could not complete this request: ${reason.detail} External fallback was also unavailable. No action was executed.`:payload?.reply,source=failed?'failed_closed':'external_fallback',live=emitRequestTelemetry({startedAt,input,reply,source,confidence:cos?.confidence??null,provenance:cos?.provenance,externalAiInvoked:!failed});save(sessionId,userId,input,reply,source,ep,live);return NextResponse.json({...payload,...(failed?{reply,source:'cos-independent-reasoner-unavailable'}:{}),cos_first_attempted:Boolean(cos)||Boolean(localError),cos_first_handled:Boolean(cos?.handled),cos_first_confidence:cos?.confidence??null,confidence_threshold:confidenceThreshold(),cos_first_reason:reason.detail,escalation_reason_code:reason.code,independent_reasoner:health,cos_first_provenance:cos?.provenance??null,execution_provenance:ep,external_ai_invoked:!failed,external_fallback_invoked:true,external_fallback_succeeded:!failed,isolation_mode:false,live_telemetry:live},{status:response.status})}catch(e){logEscalation({event:'external_escalation_result_unparsed',reason_code:reason.code,status:response.status,error:e instanceof Error?e.message:String(e)});return response}}
